
#!/bin/bash
set -euo pipefail
REPO_URL="https://github.com/dragoshelemenet/playspotstore.git"
if ! command -v git >/dev/null 2>&1; then echo "Git is required. Run: xcode-select --install"; exit 1; fi
if ! command -v python3 >/dev/null 2>&1; then echo "Python 3 is required. Install with: brew install python"; exit 1; fi
WORKDIR=$(mktemp -d "${TMPDIR:-/tmp}/playspot-neon.XXXXXX")
echo "Cloning PlaySpotStore main branch..."
git clone --depth 1 --branch main "$REPO_URL" "$WORKDIR/playspotstore"
cd "$WORKDIR/playspotstore"
mkdir -p neon-assets
python3 - <<'PYASSET'
import base64
from pathlib import Path
Path("neon-assets/accessories.webp").write_bytes(base64.b64decode(""))
PYASSET
python3 - <<'PYASSET'
import base64
from pathlib import Path
Path("neon-assets/console.webp").write_bytes(base64.b64decode(""))
PYASSET
python3 - <<'PYASSET'
import base64
from pathlib import Path
Path("neon-assets/neon-hero.webp").write_bytes(base64.b64decode(""))
PYASSET
python3 - <<'PYASSET'
import base64
from pathlib import Path
Path("neon-assets/nintendo.webp").write_bytes(base64.b64decode(""))
PYASSET
python3 - <<'PYASSET'
import base64
from pathlib import Path
Path("neon-assets/ps4.webp").write_bytes(base64.b64decode(""))
PYASSET
python3 - <<'PYASSET'
