" xmlns="http://www.w3.org/2000/svg" aria-hidden="true"><path d="M17 16C12 15 8 18 6 25L2 35C0 44 8 48 14 42L21 35H43L50 42C56 48 64 44 62 35L58 25C56 18 52 15 47 16L42 18H22L17 16Z" stroke="currentColor" stroke-width="2.5"/><path d="M17 23V34M11.5 28.5H22.5" stroke="#7bfcb7" stroke-width="3" stroke-linecap="round"/><circle cx="45" cy="25" r="2.5" fill="#b47cff"/><circle cx="51" cy="30" r="2.5" fill="#b47cff"/><circle cx="39" cy="30" r="2.5" fill="#b47cff"/><circle cx="45" cy="35" r="2.5" fill="#b47cff"/><path d="M26 16l-1-6 6 2 5-6 5 7" stroke="#70fba4" stroke-width="2" stroke-linecap="round"/></svg><span>PlaySpotStore</span></a>\n<nav><ul id="main-menu"><li><a href="#contact">КОНТАКТЫ</a></li><li><a href="#" data-category-id="ps4">ИГРЫ PS4</a></li><li><a href="#" data-category-id="ps5">ИГРЫ PS5</a></li><li><a href="#" onclick="event.preventDefault();showPlatformNotice(\'nintendo\')">NINTENDO</a></li><li><a href="#" onclick="event.preventDefault();showPlatformNotice(\'xbox\')">XBOX</a></li><li><a href="#" data-category-id="console">КОНСОЛИ</a></li><li><a href="#" data-category-id="accessories">АКСЕССУАРЫ</a></li><li class="mobile-search-bar"><input type="text" id="mobile-search-input" placeholder="Искать игру..." aria-label="Искать игры"><div class="mobile-search-suggestions" id="mobile-search-suggestions"></div></li></ul><div class="search-bar desktop-search-bar"><input type="text" id="search-input" placeholder="Искать игру..." aria-label="Искать игры"><div class="search-suggestions" id="search-suggestions"></div></div></nav><div class="hamburger" id="hamburger" role="button" tabindex="0" aria-label="Toggle menu" aria-expanded="false"><i class="bx bx-menu"></i></div></header>'}
HEROES={'ro': '<section class="hero" id="acasa"><div class="hero-art"><img src="neon-assets/neon-hero.webp" width="890" height="365" alt="PlaySpot Store gaming console and neon controllers" fetchpriority="high"></div><div class="hero-copy"><h1>Joacă. Descoperă. Câștigă.</h1><p>PlaySpotStore – Cel mai popular magazin de jocuri și accesorii<br>PlayStation, Xbox și Nintendo din Moldova!</p></div><div class="category-deck"><button type="button" class="category-tile ps4" onclick="openCategoryModal(\'ps4\')" aria-label="JOCURI PS4"><img src="neon-assets/ps4.webp" alt="" loading="eager"><span>JOCURI PS4</span></button><button type="button" class="category-tile ps5" onclick="openCategoryModal(\'ps5\')" aria-label="JOCURI PS5"><img src="neon-assets/ps5.webp" alt="" loading="eager"><span>JOCURI PS5</span></button><button type="button" class="category-tile nintendo" onclick="showPlatformNotice(\'nintendo\')" aria-label="NINTENDO"><img src="neon-assets/nintendo.webp" alt="" loading="eager"><span>NINTENDO</span></button><button type="button" class="category-tile xbox" onclick="showPlatformNotice(\'xbox\')" aria-label="XBOX"><img src="neon-assets/xbox.webp" alt="" loading="eager"><span>XBOX</span></button><button type="button" class="category-tile console" onclick="openCategoryModal(\'console\')" aria-label="CONSOLE"><img src="neon-assets/console.webp" alt="" loading="eager"><span>CONSOLE</span></button><button type="button" class="category-tile accessories" onclick="openCategoryModal(\'accessories\')" aria-label="ACCESORII"><img src="neon-assets/accessories.webp" alt="" loading="eager"><span>ACCESORII</span></button></div></section>', 'ru': '<section class="hero" id="acasa"><div class="hero-art"><img src="neon-assets/neon-hero.webp" width="890" height="365" alt="PlaySpot Store gaming console and neon controllers" fetchpriority="high"></div><div class="hero-copy"><h1>Играй. Открывай. Побеждай.</h1><p>PlaySpotStore — Магазин игр и аксессуаров<br>PlayStation, Xbox и Nintendo в Молдове!</p></div><div class="category-deck"><button type="button" class="category-tile ps4" onclick="openCategoryModal(\'ps4\')" aria-label="ИГРЫ PS4"><img src="neon-assets/ps4.webp" alt="" loading="eager"><span>ИГРЫ PS4</span></button><button type="button" class="category-tile ps5" onclick="openCategoryModal(\'ps5\')" aria-label="ИГРЫ PS5"><img src="neon-assets/ps5.webp" alt="" loading="eager"><span>ИГРЫ PS5</span></button><button type="button" class="category-tile nintendo" onclick="showPlatformNotice(\'nintendo\')" aria-label="NINTENDO"><img src="neon-assets/nintendo.webp" alt="" loading="eager"><span>NINTENDO</span></button><button type="button" class="category-tile xbox" onclick="showPlatformNotice(\'xbox\')" aria-label="XBOX"><img src="neon-assets/xbox.webp" alt="" loading="eager"><span>XBOX</span></button><button type="button" class="category-tile console" onclick="openCategoryModal(\'console\')" aria-label="КОНСОЛИ"><img src="neon-assets/console.webp" alt="" loading="eager"><span>КОНСОЛИ</span></button><button type="button" class="category-tile accessories" onclick="openCategoryModal(\'accessories\')" aria-label="АКСЕССУАРЫ"><img src="neon-assets/accessories.webp" alt="" loading="eager"><span>АКСЕССУАРЫ</span></button></div></section>'}
from pathlib import Path
import re
for name,lang,categories in [('index.html','ro','data/categories.json'),('ru.html','ru','data/categories_ru.json')]:
    p=Path(name)
    raw=p.read_text(encoding='utf-8')
    # Idempotent install, avoids stacking styles on repeat runs.
    if 'neon-redesign.css' in raw:
        print(name, 'already redesigned; preserving current version')
        continue
    h=HEADERS[lang]
    r=HEROES[lang]
    raw,n=re.subn(r'<header>.*?</header>', lambda m:h,raw,count=1,flags=re.S|re.I)
    if n!=1: raise RuntimeError('Could not locate the header in '+name)
    raw,n=re.subn(r'<section\s+class="hero"\s+id="acasa"\s*>.*?</section>',lambda m:r,raw,count=1,flags=re.S|re.I)
    if n!=1: raise RuntimeError('Could not locate the hero section in '+name)
    # The old page uses a giant inline stylesheet; put the new stylesheet after it.
    pos=raw.find('<body>')
    if pos<0:raise RuntimeError('Could not locate body in '+name)
    raw=raw[:pos]+'<link rel="stylesheet" href="neon-redesign.css?v=20261104">\n'+raw[pos:]
    # Existing categories are dynamically appended to the menu; skip already-listed entries.
    target='cats.forEach(cat => {'
    assert target in raw, 'Category menu code changed in '+name
    raw=raw.replace(target, '''cats.forEach(cat => {
      if (mainMenu.querySelector('[data-category-id="' + cat.id + '"]')) return;''',1)
    # Notice for platforms which do not yet have a corresponding JSON product catalogue.
    snippet='''\n<script>
function showPlatformNotice(platform) {
  const ru = document.documentElement.lang === 'ru';
  const name = platform === 'nintendo' ? 'Nintendo' : 'Xbox';
  const message = ru ? 'Каталог ' + name + ' пока не добавлен. Напишите нам, чтобы узнать о наличии.' : 'Catalogul ' + name + ' nu este încă disponibil online. Contactează-ne pentru disponibilitate.';
  const existing = document.getElementById('platform-notice');
  if (existing) existing.remove();
  const modal = document.createElement('div');
  modal.id = 'platform-notice';
  modal.className = 'modal active';
  modal.setAttribute('role','dialog');
  modal.setAttribute('aria-modal','true');
  modal.innerHTML = '<div class="modal-content" style="max-width:450px;margin:12vh auto;padding:32px;position:relative">' +
    '<button class="close" type="button" aria-label="Close" style="position:absolute;right:16px;top:8px;font-size:28px">&times;</button>' +
    '<h2>' + name + '</h2><p style="margin:18px 0 25px">' + message + '</p>' +
    '<a class="modal-button" style="display:inline-block;padding:12px 18px" href="https://www.instagram.com/PlaySpotStore" target="_blank" rel="noopener">Instagram</a></div>';
  document.body.appendChild(modal);
  const close = () => {modal.remove(); if (!document.querySelector('.modal.active')) document.body.style.overflow = '';};
  modal.querySelector('.close').addEventListener('click',close);
  modal.addEventListener('click',event=>{if(event.target===modal)close();});
  modal.addEventListener('keydown',event=>{if(event.key==='Escape')close();});
  document.body.style.overflow = 'hidden';
  modal.querySelector('.close').focus();
}
// Existing hamburger remains functional; add Enter/Space keyboard activation.
document.getElementById('hamburger')?.addEventListener('keydown',event=>{
  if(event.key==='Enter'||event.key===' '){event.preventDefault();event.currentTarget.click();}
});
</script>\n'''
    raw=raw.replace('</body>',snippet+'</body>',1)
    p.write_text(raw,encoding='utf-8')
    print('Updated', name)

PYPATCH
echo "Checking changed files..."
git status --short
if git diff --quiet && [ -z "$(git ls-files --others --exclude-standard)" ]; then echo "Nothing new to commit.";exit 0;fi
git add index.html ru.html neon-redesign.css neon-assets/
git -c user.name="PlaySpotStore Update" -c user.email="playspotstore-update@users.noreply.github.com" commit -m "Redesign storefront with reference-inspired neon gaming homepage"
echo "Pushing changes to GitHub main..."
if git push origin HEAD:main; then
  echo "SUCCESS: GitHub updated. Visit https://playstationspot.store/"
else
  echo "Push not authorized. Your changes are saved in $PWD"
  echo "Sign in to GitHub on your Mac (e.g. gh auth login && gh auth setup-git), then run: cd '$PWD' && git push origin HEAD:main"
  exit 1
fi
